def patch_file(path, ids):
    s = open(path, encoding="utf-8").read()
    for cid in ids:
        diff, title, brief, hints, sol, verify = P[cid]
        m = re.search(r'  p\(\{\n    id: "%s".*?\n  \}\),\n' % cid, s, re.S)
        if not m:
            print(f"NOT FOUND {cid} in {path}"); sys.exit(1)
        v = f'    mutating: true,\n    verify: "{verify}",\n' if verify else '    mutating: true,\n'
        block = (f'  p({{\n    id: "{cid}", difficulty: "{diff}",\n'
                 f'    title: "{title}",\n'
                 f'    brief: "{brief}",\n'
                 f'    hints: [{", ".join(chr(34)+h+chr(34) for h in hints)}],\n'
                 f'    solution: "{sol}",\n{v}  }}),\n')
        s = s[:m.start()] + block + s[m.end():]
    open(path, "w", encoding="utf-8").write(s)
    print(f"ok {path}: {len(ids)} problems")

